import http from 'k6/http';
import { check } from 'k6';

export const options = {
  vus: 1,
  iterations: 1,
};

export default function () {
  const base = __ENV.BASE_URL;

  const loginRes = http.post(
    `${base}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  check(loginRes, { 'login ok': (r) => r.status >= 200 && r.status < 300 });

  const csrf = loginRes.json('csrf');

  const productsRes = http.get(`${base}/products`);
  check(productsRes, { 'products ok': (r) => r.status >= 200 && r.status < 300 });

  const cartRes = http.post(
    `${base}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  check(cartRes, { 'cart ok': (r) => r.status >= 200 && r.status < 300 });

  const checkoutRes = http.post(
    `${base}/checkout`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  check(checkoutRes, { 'checkout ok': (r) => r.status >= 200 && r.status < 300 });
}
